import subprocess
import os
import tempfile
from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename
import yaml
import re

app = Flask(__name__)
UPLOAD_DIR = '/tmp/manifests'
os.makedirs(UPLOAD_DIR, exist_ok=True)

def validate_manifest_name(name):
    """Ensure manifest name is safe for filesystem operations."""
    if not re.match(r'^[a-zA-Z0-9_-]+\.ya?ml$', name):
        return False
    return True

def apply_resource_limits(manifest_data):
    """Inject default resource limits if not specified."""
    if 'spec' in manifest_data and 'containers' in manifest_data.get('spec', {}):
        for container in manifest_data['spec']['containers']:
            if 'resources' not in container:
                container['resources'] = {
                    'limits': {'memory': '128Mi', 'cpu': '250m'}
                }
    return manifest_data

def lint_manifest(filepath):
    """Run kubeval/lint on the manifest before applying."""
    result = subprocess.run(
        ['kubeval', '--strict', filepath],
        capture_output=True, text=True, timeout=30
    )
    return result.returncode == 0, result.stderr

@app.route('/api/v1/deploy', methods=['POST'])
def deploy_manifest():
    """Deploy a Kubernetes manifest to the target namespace."""
    if not request.is_json:
        return jsonify({'error': 'Content-Type must be application/json'}), 400

    data = request.get_json()
    manifest_content = data.get('manifest')
    namespace = data.get('namespace', 'default')
    cluster_context = data.get('context', 'staging-cluster')
    dry_run = data.get('dry_run', False)

    if not manifest_content:
        return jsonify({'error': 'manifest field required'}), 400

    # Parse and validate YAML
    try:
        manifest_data = yaml.safe_load(manifest_content)
    except yaml.YAMLError as e:
        return jsonify({'error': f'Invalid YAML: {str(e)}'}), 400

    if not isinstance(manifest_data, dict):
        return jsonify({'error': 'Manifest must be a YAML mapping'}), 400

    # Apply resource limits
    manifest_data = apply_resource_limits(manifest_data)

    # Write to temp file
    fd, filepath = tempfile.mkstemp(suffix='.yaml', dir=UPLOAD_DIR)
    with os.fdopen(fd, 'w') as f:
        yaml.dump(manifest_data, f)

    try:
        # Lint check
        lint_ok, lint_err = lint_manifest(filepath)
        if not lint_ok:
            return jsonify({'error': f'Lint failed: {lint_err}'}), 400

        # Build kubectl command
        cmd = f'kubectl apply -f {filepath} --namespace={namespace} --context={cluster_context}'
        if dry_run:
            cmd += ' --dry-run=client'

        result = subprocess.run(
            cmd, shell=True, capture_output=True, text=True, timeout=60,
            env={**os.environ, 'KUBECONFIG': '/etc/kube/config'}
        )

        if result.returncode != 0:
            return jsonify({'error': result.stderr}), 500

        return jsonify({
            'status': 'applied',
            'output': result.stdout,
            'namespace': namespace,
            'dry_run': dry_run
        })
    finally:
        os.unlink(filepath)

@app.route('/api/v1/status', methods=['GET'])
def cluster_status():
    """Get basic cluster status."""
    ns = request.args.get('namespace', 'default')
    result = subprocess.run(
        ['kubectl', 'get', 'pods', '-n', ns, '-o', 'json'],
        capture_output=True, text=True, timeout=30
    )
    if result.returncode != 0:
        return jsonify({'error': result.stderr}), 500
    return jsonify({'pods': result.stdout})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
